-- +goose Up
-- A file being sent in chunks. While file_id is NULL, the row also holds its size
-- on the account, so that two uploads can't both count on the same free space.
CREATE TABLE upload_sessions (
    -- Generated by the app, because the encrypted address is bound to this ID.
    id                uuid PRIMARY KEY,
    user_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    connection_id     uuid NOT NULL REFERENCES storage_connections (id) ON DELETE CASCADE,
    folder_id         uuid REFERENCES folders (id) ON DELETE CASCADE,
    name              text NOT NULL,
    content_type      text NOT NULL,
    size              bigint NOT NULL CHECK (size > 0),
    received          bigint NOT NULL DEFAULT 0,
    -- The browser's modified time, in milliseconds. After a reload the file has to
    -- be picked again, and this is how the browser tells it's the same one.
    last_modified     bigint NOT NULL DEFAULT 0,
    -- The session's address grants access to the upload, so it's sealed like a
    -- token. NULL before the provider has answered, and again once it's finished.
    secret_key_id     text,
    secret_ciphertext bytea,
    -- Set when it finishes, so a browser that lost the answer can still find out.
    file_id           uuid REFERENCES files (id) ON DELETE CASCADE,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX upload_sessions_user_id_idx ON upload_sessions (user_id);
CREATE INDEX upload_sessions_updated_at_idx ON upload_sessions (updated_at);

-- +goose Down
DROP TABLE upload_sessions;
